      "Чисте повітря, заворожуючі полонини і краєвиди, сходження на вершини гір Високий Верх та Ільзу, подорож до Павлового потічка та відвідування національного музею у м.Сколе, проживання на турбазі &quot;Полонина&quot; - усе це справило незабутнє враження на учнів, показало красу рідного краю, сприяло вихованню взаємоповаги та взаємовиручки, згуртувало учнівські колективи.",
      "Ми вдячні #Роману Суховичу, випускнику нашої школи, який гостинно зустрів односельчан у м.Сколе і допоміг у змістовному відпочинку; #Наталії Прохніцькій - гіду нашої групи, яка провела учнів вершинами гір і почастувала карпатськими стравами.",
      "Слава нашим ЗСУ за можливість мандрувати стежинами рідного краю.",
