      "Діти - наш найдорожчий скарб, наша радість, наше майбутнє. Дуже хочеться, щоб усі діти нашої рідної України щодня були радісними та щасливими. Щиро дякуємо нашим захисникам за можливість навчатися і проводити такі заходи.",
      "Шановні друзі, колеги-педагоги, працівники, учні, батьки! Сердечно вітаємо усіх із світлим святом Великодня! Нехай Воскресіння Христове наповнює серця радістю, світло Божественної любові зігріває рідних і близьких, а віра допомагає долати труднощі! Нехай панують у ваших родинах любов і доброта, турбота один про одного, а воскреслий Христос принесе перемогу і процвітання нашій Україні!",
      "Христос Воскрес!",
