      "Привітати іменинницю цього зимового дня завітала Ірина Анатоліївна Бродик, голова об&#39;єднаної профспілкової організації освітян колишнього Жовківського району, яка щиро подякувала іменинниці за мудрість, щедрість душі, за велику відданість професії і побажала здоров&#39;я.",
      "Приємною несподіванкою для ювілярки були привітання її випускників.",
