      "Здобувачі освіти читали твори, малювали ілюстрації до прочитаного, взяли участь у вікторині &quot; З якої казки?&quot; та конкурсі виразного читання віршів.Старшокласники провели літературні посиденьки до 130- річчя з дня народження Миколи Хвильового.",
