      "Допомагати нашим захисникам, які боронять нашу землю, - святий обов&#39;язок кожного. Цими днями колектив нашого закладу додав різдвяного духу з рідного дому нашим славним бійцям - землякам з 80 окремої десантно-штурмової бригади ДШВ та 214 бригади батальйону ОРFOR .",
      "Дякуємо усім небайдужим!",
      "Слава Україні! Героям Слава!",
