      "Напередодні світлих Пасхальних днів приємна звістка завітала у Липницький ЗЗСО І-ІІІ ступенів Рава-Руської міської ради. Суховича Ярослава Романовича, директора закладу, нагороджено Подякою МОН України та Почесною грамотою Львівської обласної державної адміністрації за багаторічну сумлінну працю на ниві розбудови національної освіти, вагомий внесок у навчання і виховання підростаючого покоління, за активну життєву позицію та професійні досягнення.",
