      "Ми бажаємо Вам, Ярославе Романовичу, невпинного руху вперед, успішного здійснення всіх планів та задумів. А підґрунтям щасливого життя та плідної професійної діяльності хай буде міцне здоров&#39;я, серце сповнене любові і добра, натхненна думка й щирі почуття. Щоб життя було світлим і радісним, як цей святковий день, а дружні вітання додали життєвої наснаги у скабничку Вашої душі. Нехай шана освітян та Ваших учнів буде подякою Вам за плідну працю, чуйність, уміння творити добро.",
