      "10 -11 класів – не дає їм права бути претендентами на нагородження золотою «За особливі успіхи у навчанні» та срібною «За успіхи у навчанні» медалями.",
      "Річна оцінка коригуванню не підлягає!",
      "Декларація",
      "прав",
      "дитини",
      "(звернення",
      "дітей",
      "дорослих)",
      "Ми — діти світу. Хто б не були наші батьки, де б ми не жили і в що б не вірили, поводьтеся з нами як з рівними. Ми гідні того, щоб отримувати все найкраще з того, що може дати світ.",
      "Захищайте нас, щоб ми мали мож­ливість рости гідно й вільно.",
      "Нехай у нас буде ім&#39;я і земля, яку ми можемо назвати своєю.",
      "Ми не маємо мерзнути, і в нас має бути завжди дах над головою. Забезпечте нас їжею та місцем для ігор. Якщо ми за­хворіємо, то нам потрібен догляд.",
      "Якщо у нас є проблеми у фізичному чи розумовому розвитку, Ви ще більше",
