  "правила-прийому-до-ззсо-зарахування-до-1-класу-переведення-учнів": {
    "title": "Порядок",
    "body": [
      "Порядок",
      "зарахування, відрахування та переведення учнів",
      "у 2025/2026 н.р.",
      "З 1 серпня 2024 року набув чинності наказ Міністерства освіти і науки України від 20.05.2024 № 714 «Про затвердження Змін до Порядку зарахування, відрахування та переведення учнів до державних та комунальних закладів освіти для здобуття повної загальної середньої освіти».",
      "З текстом Порядку зі змінами можна ознайомитись тут:",
      "https://zakon.rada.gov.ua/laws/show/z0564-18#Text",
      "Найважливіші зміни:",
      "Зарахування дітей до закладів освіти для здобуття початкової, базової чи профільної середньої освіти за денною формою навчання; переведення учнів з одного закладу освіти до іншого, відрахування учнів із закладів освіти з 1 серпня 2024 року відбувається",
      "ВИКЛЮЧНО з використанням електронних сервісів: програмно-апаратного комплексу «Автоматизований інформаційний комплекс освітнього менеджменту» (АІКОМ) або засобами Єдиного державного вебпорталу електронних послуг (Портал Дія).",
      "Відповідно до наказу Міністерства освіти і науки України «Про затвердження Змін до Порядку зарахування, відрахування та переведення учнів до державних та комунальних закладів освіти для здобуття повної загальної середньої освіти, заява про зарахування дитини до школи може бути подана одним із батьків або повнолітньою особою:",
      "особисто (нарочно) або електронною поштою, факсом, іншими засобами електронного зв’язку;",
      "в електронній формі з використанням АІКОМ або онлайн-сервісів.",
      "Накази керівника закладу освіти про зарахування дітей, переведення, відрахування учнів формуються автоматично в електронній формі засобами АІКОМ.",
      "Кожний заклад має визначити відповідального працівника закладу освіти, органу управління у сфері освіти, які відповідно до своїх посадових обов’язків та/або наказу керівника забезпечують організацію зарахування дітей, переведення, відрахування учнів з використанням АІКОМ або онлайн-сервісів.",
      "З 1 серпня 2024 року довідки із закладів освіти про можливість зарахування, факт зарахування або незарахування НЕ ПОТРІБНІ. Достовірність наданих до закладу документів перевіряється засобами АІКОМ автоматично, зокрема, документи, що підтверджують місце проживання/перебування на території обслуговування.",
      "Про прийом до 1-го класу 2023 року",
      "Батькам майбутніх першокласників",
      "Які нормативні документи регулюють вступ до 1 класу?",
      "Порядок зарахування, відрахування та переведення учнів до державних та комунальних закладів освіти для здобуття повної загальної середньої освіти",
      "регламентується",
      "наказом Міністерства освіти i науки України від 16 квітня 2018 року № 367 , зареєстрований в Міністерстві юстиції України 05 травня 2018 р. за № 564/32016.",
      "https://zakon.rada.gov.ua/laws/show/z0564-18",
      "Відповідно до статті 18 Закону України «Про загальну середню освіту» зарахування дітей до першого класу початкової школи загальноосвітніх навчальних закладів державної та комунальної форми власності (у тому числі ліцеїв, гімназій, колегіумів, коледжів, що містять у своїй структурі школу І ступеня) здійснюється на безконкурсній основі.",
      "Які необхідні документи для зарахування до 1 класу?",
      "Необхідно одному з батьків до 31 травня надати:",
      "заяву про зарахування,",
      "копію свідоцтва про народження дитини та оригінал;",
      "оригінал медичної довідки за",
      "формою первинної облікової документації № 086-1/о «Довідка учня загальноосвітнього навчального закладу про результати обов’язкового медичного профілактичного огляду»",
      ", затвердженою наказом Міністерства охорони здоров’я України від 16 серпня 2010 року № 682, зареєстрованим в Міністерстві юстиції України 10 вересня 2010 року за № 794/18089.",
      "https://zakon.rada.gov.ua/laws/show/z0794-10#Text",
      "Львівський"
    ],
    "links": [
      "https://drive.google.com/file/d/1p_cB6XdxQiARHchTtcoXk_Q-ABfwa7G3/view?usp=sharing"
    ]
  },
