      "https://zakon.rada.gov.ua/laws/show/2657-19",
      "Процедура подання (з дотриманням конфіденційності) заяви про випадки булінгу (цькування)",
      "Усі здобувачі освіти, педагогічні працівники закладу, батьки та інші учасники освітнього процесу повинні обов’язково повідомити директора навчального закладу про випадки булінгу (цькування), учасниками або свідками якого вони стали, або підозрюють про його вчинення по відношенню до інших осіб за зовнішніми ознаками, або про які отримали достовірну інформацію від інших осіб.",
      "На ім’я директора закладу пишеться заява (конфіденційність гарантується) про випадок булінгу (цькування).",
      "Директор закладу видає наказ про проведення розслідування та створення комісії з розгляду випадку булінгу (цькування), скликає її засідання.",
      "До складу такої комісії входять педагогічні працівники (у тому числі психолог, соціальний педагог), батьки постраждалого та булерів, керівник навчального закладу та інші зацікавлені особи.",
      "Рішення комісії реєструються в окремому журналі, зберігаються в паперовому вигляді з оригіналами підписів усіх членів комісії.",
      "Порядок реагування на доведені випадки булінгу (цькування) та відповідальність осіб, причетних до булінгу",
      "Директор закладу має розглянути звернення у встановленому порядку.",
      "Директор закладу створює комісію з розгляду випадків булінгу, яка з’ясовує обставини булінгу.",
      "Якщо комісія визнала, що це був булінг, а не одноразовий конфлікт, то директор",
      "закладу освіти",
      "повідомляє уповноважені підрозділи органів Національної поліції України та Службу у справах дітей.",
      "Особи, які за результатами розслідування є причетними до булінгу, несуть відповідальність відповідно до частини другої статті 13 (вчинення правопорушень за статтею 173",
      "4) Кодексу України про адміністративні правопорушення.",
      "Процедура подання учасниками освітнього процесу",
      "заяв про випадки булінгу (цькування):",
      "1. Подати заяву на ім’я керівника закладу освіти про випадок булінгу, учасником або свідком якого ви стали.",
      "2. Відповідно до заяви керівник закладу видає рішення про проведення розслідування із визначенням уповноважених осіб.",
      "3. Для прийняття рішення за результатами розслідування керівник закладу освіти створює наказом комісію з розгляду випадків булінгу та скликає засідання.",
      "4. Якщо Комісія визнала, що це булінг(цькування), а не одноразовий конфлікт чи сварка, тобто відповідні дії носять систематичний характер, то керівник закладу повідомляє уповноважені підрозділи органів Національної поліції України ( ювенальна превенція) та Службу у справах дітей.",
